def _clone_annotation(annotation: Annotation) -> Annotation:
    """
    Return a deep copy of the inpt annotation.
    """
    return deepcopy(annotation)


def _coerce_fill(image: Image.Image, fill):
    """
    Coerce fill values so they work for RGB, RGBA, L, etc.
    """
    bands = image.getbands()
    n_bands = len(bands)

    if isinstance(fill, int):
        if n_bands == 1:
            return fill
        if "A" in bands:
            return tuple([fill] * (n_bands - 1) + [255])
        return tuple([fill] * n_bands)

    if isinstance(fill, tuple):
        if n_bands == 1:
            return int(fill[0])

        if len(fill) == n_bands:
            return fill

        if len(fill) > n_bands:
            return fill[:n_bands]

        missing = n_bands - len(fill)
        if "A" in bands:
            return tuple(fill) + tuple([255] * missing)

        return tuple(fill) + tuple([fill[-1]] * missing)

    return fill


def _box_intersection(box1, box2):
    i_x0 = max(box1[0], box2[0])
    i_y0 = max(box1[1], box2[1])
    i_x1 = min(box1[2], box2[2])
    i_y1 = min(box1[3], box2[3])
    if i_x0 >= i_x1 or i_y0 >= i_y1:
        return [0, 0, 0, 0]
    return [i_x0, i_y0, i_x1, i_y1]


def _box_area(box):
    x0, y0, x1, y1 = box
    return abs(x1 - x0) * abs(y1 - y0)


