class RandomMasking(Transform):
    """
    Mask randomly a part of an image with the given fill color.
    min_width, max_width, min_height and max_height are between 0 and 1.
    """
    def __init__(
            self,
            p: float,
            min_width: float,
            max_width: float,
            min_height: float,
            max_height: float,
            max_rectangles: int,
            fill=(0, 0, 0),
    ):
        super().__init__()
        self.p = p
        self.min_width = min_width
        self.max_width = max_width
        self.min_height = min_height
        self.max_height = max_height
        self.max_rectangles = max_rectangles
        self.fill = fill

    @classmethod
    def from_json(cls, data: dict) -> "RandomMasking":
        return cls(
            p=data["p"],
            min_width=data["min_width"],
            max_width=data["max_width"],
            min_height=data["min_height"],
            max_height=data["max_height"],
            max_rectangles=data["max_rectangles"],
            fill=data.get("fill", (0, 0, 0))
        )

    def to_json(self) -> dict:
        return {
            "p": self.p,
            "min_width": self.min_width,
            "min_height": self.min_height,
            "max_width": self.max_width,
            "max_height": self.max_height,
            "max_rectangles": self.max_rectangles,
            "fill": self.fill
        }

    def __call__(self, image: Image.Image, labels: Annotation,) -> tuple[Image.Image, Annotation]:
            new_labels = _clone_annotation(labels)
            if random.random() > self.p:
                return image, new_labels
            # now draw on the image random rectangles
            W, H = image.size
            out = image.copy()
            draw = ImageDraw.Draw(out)
            n_rectangles = random.randint(1, self.max_rectangles)
            for _ in range(n_rectangles):
                erase_w = int(random.uniform(self.min_width, self.max_width) * W)
                erase_h = int(random.uniform(self.min_height, self.max_height) * H)
                # determine the rectangle points
                x0 = random.randint(0, W - erase_w)
                y0 = random.randint(0, H - erase_h)
                x1 = x0 + erase_w
                y1 = y0 + erase_h
                # draw the rectangle
                rect = (x0, y0, x1, y1)
                draw.rectangle(
                    rect,
                    fill=_coerce_fill(image, self.fill),
                )
                # update the labels
                self._update_labels(new_labels, (x0 / W, y0 / H, x1 / W, y1 / H), W, H)
            return out, new_labels

    def _box_percentage(self, box, mask):
        return _box_area(_box_intersection(box, mask)) / _box_area(box)

    def _update_labels(self, labels: Annotation, rect: tuple[float, float, float, float], W, H):
        """
        Update the labels for the masking transform.
        """
        kept_pairs = []
        for pair in labels.cloth.pairs:
            # if the given masking rectangle contains the button center, the pair disappear
            button_box = pair.button.bbox.to_x1y1x2y2()
            if self._box_percentage(button_box, rect) > 0.5:
                pair.button.visible = False
                pair.counterpart.visible = False
                continue
            # if the given masking rectangle contains the counterpart center, the counterpart is set to invisible
            counterpart_box = pair.counterpart.bbox.to_x1y1x2y2()
            if self._box_percentage(counterpart_box, rect) > 0.5:
                pair.counterpart.visible = False
            kept_pairs.append(pair)
        labels.cloth.pairs = kept_pairs


