class RandomFlip(Transform):
    def __init__(self, p: float, direction: str):
        super().__init__()
        self.p = p
        self.direction = direction

    @classmethod
    def from_json(cls, data: dict) -> "RandomFlip":
        return cls(
            p=data["p"],
            direction=data["direction"]
        )

    def to_json(self) -> dict:
        return {
            "p": self.p,
            "direction": self.direction
        }

    def _flip_bbox(self, bbox: BoundingBox) -> BoundingBox:
        x1, y1, x2, y2 = bbox.to_x1y1x2y2()
        match self.direction:
            case "horizontal":
                return BoundingBox.from_x1y1x2y2(1.0 - x2, y1, 1.0 - x1, y2)
            case "vertical":
                return BoundingBox.from_x1y1x2y2(x1, 1.0 - y1, x2, 1.0 - y2)
            case _: raise Exception("Unreachable")

    def _update_labels(self, labels: Annotation):
        for pair in labels.cloth.pairs:
            pair.button.bbox = self._flip_bbox(pair.button.bbox)
            pair.counterpart.bbox = self._flip_bbox(pair.counterpart.bbox)

    def __call__(self, image: Image.Image, labels: Annotation,) -> tuple[Image.Image, Annotation]:
        new_labels = _clone_annotation(labels)
        if random.random() >= self.p:
            return image, new_labels
        match self.direction:
            case "horizontal":
                flipped = ImageOps.mirror(image)
            case "vertical":
                flipped = ImageOps.flip(image)
            case _: raise Exception("Unreachable")
        self._update_labels(new_labels)
        return flipped, new_labels


class RandomQuarterTurn(Transform):
    """
    Randomly rotate the image by either +90° or -90°.

    Pillow's ROTATE_90 corresponds to a 90° counter-clockwise rotation.
    ROTATE_270 corresponds to a 90° clockwise rotation.

    The output dimensions are swapped:
        (W, H) -> (H, W)

    Bounding boxes remain normalized in cx, cy, w, h format.
    """

    def __init__(self, p: float):
        super().__init__()
        self.p = p

    @classmethod
    def from_json(cls, data: dict) -> "RandomQuarterTurn":
        return cls(
            p=data["p"]
        )

    def to_json(self) -> dict:
        return {
            "p": self.p
        }

    def _flip_bbox(self, bbox: BoundingBox, direction: str):
        x1, y1, x2, y2 = bbox.to_x1y1x2y2()
        match direction:
            case "rotate_90":
                return BoundingBox.from_x1y1x2y2(y1, 1.0 - x2, y2, 1.0 - x1)
            case "rotate_270":
                return BoundingBox.from_x1y1x2y2(1.0 - y2, x1, 1.0 - y1, x2)
            case _: raise Exception("Unreachable")

    def _update_labels(self, labels: Annotation, direction: str):
        for pair in labels.cloth.pairs:
            pair.button.bbox = self._flip_bbox(pair.button.bbox, direction)
            pair.counterpart.bbox = self._flip_bbox(pair.counterpart.bbox, direction)

    def __call__(self, image: Image.Image, labels: Annotation) -> tuple[Image.Image, Annotation]:
        new_labels = _clone_annotation(labels)
        if random.random() >= self.p:
            return image, new_labels
        rotate_counter_clockwise = random.choice((True, False))
        if rotate_counter_clockwise:
            rotated = image.transpose(_ROTATE_90)
            self._update_labels(new_labels, "rotate_90")
        else:
            rotated = image.transpose(_ROTATE_270)
            self._update_labels(new_labels, "rotate_270")
        return rotated, new_labels


